Target.m:
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% TARGET
% Defines the target class for implementation of VTP
%
% tar = Target()
%           defines an empty Target, that is, tar.Components and tar.ids
%           are the empty cell array and empty array, respectively.
% tar = Target(P)
%           where P is a 2-column matrix defines a Target with a single
%           component whose veritices are the rows of P. P is taken to
%           represent a point, segment, or (closed) polygon, depending on
%           the number of rows.
% tar = Target(C) 
%           where C is a cell array of size k where each C{:} is a 2-column
%           matrix defines a target with k components specified by the C{:}
%           as above.
% tar = Target(_,ids)
%           where ids is a vector sets tar.Components exactly as above but
%           also sets tar.Ids to ids. the length of ids must match the
%           number of components. The purpose is to associate distinct
%           components into unions effectively creating subtargets which
%           may be sought by distinct subpopulations. (See the homeToTarget
%           method.)
% Notes:
%   - If P = C{i} in the above syntaxes, then the i-th cell of
%     tar.Components contains:
%       - P itself if P has only one or two rows;
%       - polyshape(P) if P has at least three rows.
%   - homeToTarget may give unexpected results if the target has nonconvex
%     components.
%   - homeToTarget may give unexpected results if the target has
%     overlapping components with the same id.

classdef Target

properties
    Components
    Ids
end

methods
    function tar = Target(C,ids)
        arguments
            C {mustBeA(C,["cell","double"])} = cell(0)
            ids double {mustHaveSameNum(ids,C)} = ones(numel(C),1)
        end

        if isempty(C)
            tar.Components = cell(0);
            tar.Ids = [];
            return;
        end
        if isa(C,'double')
            C = {C};
        end

        k = numel(C);
        K = cell(k,1);

        for m=1:k
            P = C{m};
            if size(P,1) < 3
                K{m} = P;
                continue; 
            end

            pgon = polyshape(P);
            conv = convhull(pgon);
            if size(pgon.Vertices,1) ~= size(conv.Vertices,1)
                warning('target:nonconvex',...
                    'Possible nonconvex target region (component %d). May have unexpected results.', m);
            end
            K{m} = pgon;
        end

        tar.Components = K;
        tar.Ids = ids;
    end

    function tar = setComponent(tar,k,P)
        % Sets the k-th component of tar to (the point/segment/polygon)
        % specified by P. Throws a warning if the new component has
        % differnt combinatorial properties than the original.
        % A possible use case is moving targets.
        arguments
            tar (1,1) Target
            k (1,1) double {mustBeInteger,mustBePositive}
            P (:,2) double
        end
        K = tar.Components;
        if k > size(K,1)
            error('Second input must not exceed number of components in %s.', inputname(1));
        end
        Q = K{k};
        bothPointsOrSegs = isa(Q,'double') && isa(P,'double') && size(Q,1)==size(P,1);
        bothNGons = isa(Q,'polyshape') && isa(P,'polyshape')...
            && ( size(Q.Vertices,1)==size(P.Vertices,1)...
            || Q.numRegions == P.numRegions || Q.numHoles == P.numHoles );
        if ~(bothPointsOrSegs || bothNGons)
            warning('Changed combinatorial properties of target (component %d)', k);
        end
        if size(P,1) >= 2
            P = polyshape(P);
        end
        K{k} = P;
        tar.Components = K;
    end

    function h = homeToTarget(tar, X, target_idx)
        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        % h = homeToTarget(tar, X)
        %       where X is a 2-column matrix returns a matrix h of the same
        %       size as X whose i-th row h(i,:), the _homing vector_ is the 
        %       vector of minimum length such that X(i,:) + h(i,:) is in 
        %       the target tar. If X(i,:) is interior to a polygonal
        %       component of the target, then h(i,:) is the zero vector,
        %       naturally.
        % h = homeToTarget(tar, X, target_idx)
        %       where X is a 2-column matrix and target_idx is a vector
        %       whose length is the number of rows of X is like the
        %       previous syntax except that the i-th homing vector h(i,:) 
        %       is now the minimum legth vector such that X(i,:) + h(i,:)
        %       is contained in the union of components of target tar whose
        %       id (as specified by tar.Ids) matches target_idx(i). If
        %       target_idx(i) has no match among tar.Ids, then h(i,:) is
        %       the zero vector; this subpopulation effectively has no
        %       target.
        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        arguments
            tar (1,1) Target
            X (:,2) double
            target_idx (:,1) double {mustBeSameSize(target_idx,X)} = ones(size(X,1),1);
        end

        N = size(X,1);
        h = zeros(N,2);

        K = tar.Components;
        k = size(K,1);
        if k == 0, return; end

        ids = tar.Ids;

        d = Inf(N,1);

        for l=1:k
            P = K{l};
            J = (target_idx==ids(l));
            h0 = zeros(N,2);
            if isa(P, 'double') == 1
                if size(P,1) == 1   % P is a point
                    h0(J,:) = P - X(J,:);
                else                % P is a segment
                    for i=1:N
                        if J(i)==false, continue; end
                        y = nearestOnSegment(P',X(i,:)');
                        h0(i,:) = y'-X(i,:);
                    end
                end
            else                    % P is a polygon
                v = P.Vertices;
                for i=1:N
                    if J(i)==false || isinterior(P,X(i,:))
                        continue;
                    end
                    r = Inf;
                    for m=1:size(v,1)
                        seg = [v(m,:)' v(1+mod(m-2,size(v,1)),:)'];
                        y = nearestOnSegment(seg, X(i,:)');
                        e = y'-X(i,:);
                        r0 = dot(e,e);
                        if r0 < r
                            r = r0;
                            h0(i,:) = e;
                        end
                    end
                end
            end
            d0 = dot(h0,h0,2);
            I = J & (d0 < d);
            d(I) = d0(I);
            h(I,:) = h0(I,:);
        end    
    end

end

end

% validation
function mustHaveSameNum(C,I)
    if numel(I) ~= numel(C)
        eid = 'Size:mustBeEqual';
        msg = 'Inputs must have the same number of elements.';
        throwAsCaller(MException(eid,msg));
    end
end 
function mustBeSameSize(a,b)
    if size(a,1) ~= size(b,1)
        eid = 'Size:equalSize';
        msg = 'Third input must have as many entries as the number of ros of the first input';
        throwAsCaller(MException(eid,msg));
    end
end

alignTo.m:
function a = alignTo(U,nbhd,transition_func)

arguments
    U (:,2) double
    nbhd (:,1) cell {mustBeEqualSize(nbhd,U)}
    transition_func (1,:) char
end

N = size(U,1);
a = zeros(N,2);
g = @(x) transition(x,transition_func);
w = @(x) g(1/pi*acos(x));
for i=1:N
    ui = U(i,:);
    ui = ui/norm(ui,2);
    ui(isnan(ui)) = 0;
    J = nbhd{i};
    for j=1:size(J,2)
        uj = U(J(j),:);
        uj = uj/norm(uj,2);
        uj(isnan(uj)) = 0;
        s = dot(ui,uj);
        % due to numerical error, it can happen that |s|>1, if this is not
        % corrected, w(s) (which calls acos) will attempt to input an
        % imaginary value to g. The complex-valued acos function is
        % continuous at ±1 so this correction is well-behaved.
        if abs(s) > 1
            s = sign(s);
        end
        a(i,:) = a(i,:) + w(s)*uj;
    end
end
a = 1/6*a;

end

% validation
function mustBeEqualSize(a,b)
    if size(a,1) ~= size(b,1)
        eid = 'Size:equalSize';
        msg = 'second input must have same length as first';
        throwAsCaller(MException(eid,msg));
    end
end

dynamics.m:
%% Parameters
N = 400;
L = 1;
nu = 2.5;
tmax = 1000;

%% Target field parameters
% STATIC targets: a rectangular lattice of point targets covering the plane
% (window [-grid_half, grid_half]^2). The spacing is set separately in x
% and in y. Every agent homes toward whichever target (static lattice point
% or the collector) is nearest to it, except agents stuck to the collector
% (see below), which home toward a blend of the collector and their nearest
% lattice target.
grid_half      = 50;
grid_spacing_x = 5;      % one static target every grid_spacing_x units in x
grid_spacing_y = 5;      % ... and every grid_spacing_y units in y

% CIRCULAR MOTION of the static lattice: it moves rigidly, so that its
% center travels on a circle of radius field_radius centered on the origin.
% At time t the lattice center is at field_radius*[cos(theta) sin(theta)]
% with theta = (field_speed/field_radius)*t, so one lap takes
% 2*pi*field_radius/field_speed steps.
field_speed  = 0.2;      % speed along the circle, units per time step (agents move at up to 1); negative = clockwise
field_radius = 20;       % radius of the circle (0 = the lattice stays put)
if field_radius > 0
    field_omega = field_speed/field_radius;   % angular velocity, rad per step
else
    field_omega = 0;
end

% ONE COLLECTOR target. It does not oscillate: it goes after the agents.
%   - Capture: an agent that comes within capture_radius of the collector
%     STICKS to it. A stuck agent homes toward a blend of the collector and
%     its nearest lattice target (weight field_weight, below), so it keeps
%     feeling the target field, until it drifts farther than release_radius,
%     at which point it is released and may be re-captured.
%   - Seeking: the collector moves toward the nearest agent that is not
%     stuck, at up to collector_speed. Once every agent is stuck it moves
%     to the centroid of the group and stays there.
%   - Keeping them close: the collector slows down in proportion to how
%     far the centroid of its stuck agents trails behind it, and stops
%     when that lag reaches keep_close, so it never runs away from the
%     agents it has collected. Its speed factor is max(0, 1 - lag/keep_close).
collector_speed = 0.4;       % top speed of the collector, units per time step (agents move at up to 1)
capture_radius  = 3;         % agents closer than this stick to the collector
release_radius  = 25;        % stuck agents farther than this are released
keep_close      = 5;         % lag of the stuck group's centroid at which the collector stops
collector_start = [30 0];    % where the collector starts

% FIELD WEIGHT for stuck agents. A stuck agent still feels the target field:
% its homing direction is the blend
%   (1-field_weight)*(unit vector to the collector) + field_weight*(unit vector to its nearest lattice target),
% and that homing term then goes through the normal VTP rules (length 1-s,
% repulsion priority, alignment, Voronoi speed governor) like every other
% agent. 0 = stuck agents ignore the field (old behaviour), 1 = they ignore
% the collector.
field_weight    = 0.5;

display=true;
fixframe = false;
frameinrad = 1.2*grid_half;   % with fixframe = true the frame is centered on the moving field

fdim = 1;
M0 = L;
if fdim==2
    M0 = pi*L^2/2;
end

filename='data.mat';
erase='';

%% Initial conditions
ic_rad=.5*sqrt(N*pi/4/.91);
rng(2);
X = ic_rad*(2*rand(N,2) - 1);
rng(18);
ang = 2*pi*rand(N,1);
U = [cos(ang) sin(ang)];

% ang = 2*pi*rand(N,1);
% n1 = rand(N,2);
% n2 = pi*rand(N,2);
% X = ic_rad*( [cos(ang) sin(ang)] + .2*n1 );
% U = [-sin(ang) cos(ang)] + .25*n2;

% sep = 10;
% X = zeros(N,2);
% X(:,2) = 4*rand(N,1) - 2;
% X(1:N/2,1) = -sep;
% X(N/2+1:end,1) = sep;
% U = zeros(N,2);
% U(1:N/2,1) = 1;
% U(N/2+1:end,1) = -1;

% rad = 3;
% sep = 4;
% r = rad*rand(N,1);
% a = 2*pi*rand(N,1);
% X = sqrt(r).*[cos(a) sin(a)];
% X(1:N/2,1) = X(1:N/2,1) + sep;
% X(N/2+1:end,1) = X(N/2+1:end,1) - sep;
% U = [-sin(a) cos(a)];

% X = zeros(N,2);
% X(1:N/2,2) = 5;
% X(N/2+1:end,2) = -5;
% X(:,1) = 100*rand(N,1) - 25;
% U = zeros(N,2);
% U(1:N/2,1) = 1;
% U(N/2+1,end) = -1;

%% Initialize targets

% sR = [sep sep; -4 4]';
% sL = [-sep -sep; -4 4]';
% R = [.8 .8 .6 .5; .7 .9 .9 .6]';
% tar = Target({sL,sR},[1 2]);
ids = ones(N,1);
ids(1:N/2) = 2;
% tar = Target(1*[1 -1 -1 1; 1 1 -1 -1]');
% tar = Target([0 0]);
% tar = Target({[-w/2 0],[w/2 0]});
tar_rad = 4;
tar_ang = 2*pi/3;
tar = Target({tar_rad*[1 0],tar_rad*[cos(tar_ang) sin(tar_ang)],tar_rad*[cos(2*tar_ang) sin(2*tar_ang)]});
% tar = Target();

% --- static lattice of point targets + the collector ------------------
[gx,gy] = meshgrid(-grid_half:grid_spacing_x:grid_half, -grid_half:grid_spacing_y:grid_half);
staticPts = [gx(:) gy(:)];
nStatic = size(staticPts,1);
fieldOff = @(t) field_radius*[cos(field_omega*t) sin(field_omega*t)];   % where the lattice center is at time t

% collector state: its position and which agents are stuck to it
cp    = collector_start;
stuck = false(N,1);

% tar holds the lattice points only (the target field). It is rebuilt every
% step below, because the lattice moves. The collector is handled
% separately in the homing step, so that stuck agents can feel both.
tar = Target(mat2cell(staticPts + fieldOff(0), ones(nStatic,1), 2));

%% Preallocation of some intermediate variables
[r,a,h0,h,s,l,rho] = deal(zeros(N,1));
U1 = zeros(N,2);
Q = zeros(N,2);

%% Preallocation of time series variables
U_t = zeros(N,2,tmax);
DT_t = cell(tmax,1);


for t = 1:tmax
%% Compute step

% --- collector: capture / release, then move ---------------------------
dc = hypot(X(:,1)-cp(1), X(:,2)-cp(2));          % distance of every agent to the collector
stuck = (stuck & dc <= release_radius) | (dc <= capture_radius);

if any(stuck)
    lag = norm(mean(X(stuck,:),1) - cp);         % how far the stuck group's centroid trails
    throttle = max(0, 1 - lag/keep_close);       % slow down (down to 0) if they fall behind
else
    throttle = 1;
end

if any(~stuck)
    Xf = X(~stuck,:);                            % seek the nearest agent that is not stuck yet
    [~,kf] = min(hypot(Xf(:,1)-cp(1), Xf(:,2)-cp(2)));
    goal = Xf(kf,:);
else
    goal = mean(X,1);                            % everyone is stuck: stay with the group
end
gvec  = goal - cp;
gdist = norm(gvec);
if gdist > 0
    cp = cp + gvec/gdist * min(collector_speed*throttle, gdist);
end

% move the lattice around its circle
off = fieldOff(t);
tar = Target(mat2cell(staticPts + off, ones(nStatic,1), 2));

DT = delaunayTriangulation(X);
DT_t{t} = DT;
U_t(:,:,t) = U;
[nbhd, nearest, d] = neighborhoods(DT);
fun = @(x) transition(x,'expReciprocal');
s = arrayfun(fun, d/L);

% repulsion
r = X - X(nearest,:);
rnorm = vecnorm(r,2,2);
r = s .* r./rnorm;  % rescale to length s

% alignment
a = alignTo(U,nbhd,'expReciprocal');

% homing
hF = homeToTarget(tar,X);           % toward the nearest lattice target (the field)
hC = cp - X;                        % toward the collector
dF = vecnorm(hF,2,2);
dC = vecnorm(hC,2,2);
h0 = hF;                            % free agents: nearest target of lattice + collector
useC = dC < dF;
h0(useC,:) = hC(useC,:);
uF = hF./dF;  uF(dF==0,:) = 0;      % unit vectors (0 if already on the target)
uC = hC./dC;  uC(dC==0,:) = 0;
% stuck agents keep feeling the field: blend of collector and nearest lattice target
h0(stuck,:) = (1-field_weight)*uC(stuck,:) + field_weight*uF(stuck,:);
h = (1-s) .* h0./vecnorm(h0,2,2);   % rescale to length 1-s (VTP homing)
h(isnan(h)) = 0;                    % protect 0 entries

% direction
U1 = (r + h + nu*a)./(1 + nu);

% speed
[~,l] = voronoiProjectToBoundary(DT,U1);
M = l;
if fdim==2
    M = voronoiForwardArea(DT,U1);
end

%% plot
if display==true
    clipToVoronoi=false;

    fig = figure(1);
    scatter(X(:,1), X(:,2), '.k');
    hold on
    scatter(X(stuck,1), X(stuck,2), 14, [0.95 0.5 0.1], 'filled');   % agents stuck to the collector
    % triplot(DT,'b');
    % text(X(:,1),X(:,2),num2cell(1:N));

    % vor = voronoi(DT);
    % vor(2).Color = 'k';

    qs = 1;
    % quiver(X(:,1),X(:,2),qs*r(:,1),qs*r(:,2),'off', 'r');
    % quiver(X(:,1),X(:,2),qs*h(:,1),qs*h(:,2),'off', 'g');
    % quiver(X(:,1),X(:,2),qs*a(:,1),qs*a(:,2), 'off', 'b');

    % quiver(X(:,1),X(:,2),qs*U(:,1),qs*U(:,2),'off', 'b');
    quiver(X(:,1),X(:,2),qs*U1(:,1),qs*U1(:,2), 'b');

    % plot([X(:,1) Q(:,1)]', [X(:,2) Q(:,2)]', 'r:', 'LineWidth', 1);
    % s = min(l);
    % quiver(X(:,1), X(:,2), s*U(:,1), s*U(:,2), 'off', 'r', 'ShowArrowHead', 1, 'LineWidth', 1);
    % scatter(Q(:,1), Q(:,2), '*b');

    C = tar.Components;
    for m=1:size(C,1)
        if isa(C{m},'polyshape')
            plot(C{m},'EdgeColor','none');
        end
    end

    % static lattice targets (grey), the collector (red) and its capture radius
    scatter(staticPts(:,1)+off(1), staticPts(:,2)+off(2), 25, [.5 .5 .5], 's');
    scatter(cp(1), cp(2), 80, 'r', 'filled');
    ang = linspace(0, 2*pi, 60);
    plot(cp(1)+capture_radius*cos(ang), cp(2)+capture_radius*sin(ang), 'r:');


    hold off

    clip = [min(X,[],1); max(X,[],1)];
    if clipToVoronoi==true
        V = voronoiDiagram(DT);
        clip = [min([V; X],[],1); max([V(2:end,:); X],[],1)];
    end
    clip_width = 1.2*max(clip(2,:)-clip(1,:));
    clip_center = mean(clip,1);
    clip_lim(1:4) = clip_center(ceil((1:4)/2)) - rescale(mod(1:4,2),-1,1)*.5*clip_width;

    axis equal


    frame = [-frameinrad frameinrad -frameinrad frameinrad] + [off(1) off(1) off(2) off(2)];
    if ~fixframe
        com = mean(X);
        rmed = sqrt(median((X(:,1)-com(1)).^2+(X(:,2)-com(2)).^2));
        frame = [com(1)-3*rmed com(1)+3*rmed com(2)-3*rmed com(2)+3*rmed];
    end
    axis(frame);
    title(['$t=',num2str(t),',\; \mathrm{stuck}=',num2str(nnz(stuck)),',\; v_{col}=',num2str(collector_speed),',\; v_{field}=',num2str(field_speed),',\; R_{field}=',num2str(field_radius),',\; w_{field}=',num2str(field_weight),'$'], 'Interpreter', 'Latex');
end

%% Update

U = tanh(M/M0).*U1;
X = X + U;

%% display progress

barwidth = 60;
frac = floor(t/tmax * barwidth);
fracpct = t/tmax*100;
sofar = repmat(sprintf('\x0023'),1,frac);
yet = repmat('-',1,barwidth-frac);
progbar = ['[' sofar yet ']' ' ' sprintf('%04.1f\t%s',fracpct,filename) newline];
fprintf([erase progbar]);
erase = repmat(sprintf('\b'),1,length(progbar));
end


save("data.mat",'DT_t','U_t');

nearestOnSegment.m:
function y = nearestOnSegment(S,x)

arguments
    S (2,2) double
    x (2,1) double
end

p = S(:,1);
q = S(:,2);
a = -atan2(p(2)-q(2),p(1)-q(1));

R = [ cos(a) -sin(a); sin(a) cos(a) ];

X = R*[p q x];

while true
    [~,j] = min(X(1,1:2));
    if X(1,3) <= X(1,j)
        y0 = X(:,j);
        break;
    end

    [~,j] = max(X(1,1:2));
    if X(1,3) >= X(1,j)
        y0 = X(:,j);
        break;
    end

    y0 = [ X(1,3); X(2,1) ];
    break;
end

y = R'*y0;

end

neighborhoods.m:
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% NEIGHBORHOODS
% Get graph neighborhoods of vertices of Delaunay Triangulation
%
% Syntax:
%   [nbhd,nearest,dist] = neighborhoods(DT)
%   [nbhd,nearest,dist] = neighborhoods(DT,r)
% Input:
%   DT  :   delaunayTriangulation object
%   r   :   positive integer or Inf. topological radius of each
%           neighborhood. Default 1.
% Output:
%   nbhd:   Nx1 cell array where N is the number of points in DT. nbhd{i}
%           is a row vector containing the indices of points in DT
%           reachable from point i via a walk in DT of length at most r
%           excluding i itself.
%   nearest: Nx1 double. nearest(i) is the index of the vertex in DT
%           distinct from i which is closest to i.
%   dist:   Nx1 double. dist(i) is the distance between vertex i and its
%           nearest neighbor in DT.


function [nbhd,nearest,dist] = neighborhoods(DT,r)

arguments
    DT delaunayTriangulation
    r  (1,1) double {mustBePositiveIntegerOrInf} = 1
end

X = DT.Points;
N = size(X,1);
if r==Inf, r=N; end
E = edges(DT);
EE = [ E ; E(:,[2 1]) ];
v = ones(size(EE,1),1);
adj = sparse(EE(:,1),EE(:,2),v);
nbhd = cell(N,r);
nearest = zeros(N,1);
dist = zeros(N,1);
for i=1:N
    neighbors = find(adj(i,:)==1);
    [d,l] = min(arrayfun(@(j) norm(X(i,:)-X(j,:)), neighbors));
    dist(i) = d;
    nearest(i) = neighbors(l);
    nbhd{i,1} = neighbors;
end

neye = ones(N,N)-eye(N);  % false diagonal, true off-diagonal

if r > 1
    powAdj = eye(N);
    cumAdj = zeros(N,N);
    for k=1:r
        powAdj = powAdj*adj;
        cumAdj = cumAdj+powAdj;
        cumAdj = cumAdj & neye;
        for i=1:N
            nbhd{i,k} = find(cumAdj(i,:)~=0);
        end
        cumAdj = cumAdj | eye(N);
        if all(cumAdj,'all')
            break;
        end
    end
end

end

% validation
function mustBePositiveIntegerOrInf(a)
    if ~((a==floor(a) && a>0) || a==Inf)
        eid = 'neighborhoods:inputError';
        msg = 'Radius must be a positive integer or Inf';
        throwAsCaller(MException(eid,msg));
    end
end

poly_area.m:
function A = poly_area(x,y) 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% This function computes the centroid coordinates of a Voronoi region as
% well as its individual Voronoi energy
%
% INPUT: - x,y are the coordinates of the vertices of the polygon
%        
%    
% OUTPUT: - A is area of the polygon
%         
%
% Initially written by H.J. Sommer III - 16.12.09 - tested under MATLAB v9.0
% Modified by Ivan Gonzalez @McGill University 
% Last update: May 17th of 2018.
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% check if inputs are same size
if ~isequal( size(x), size(y) )
  error( 'X and Y must be the same size');
end

% We shift the vertices by [genx;geny] to compute quantities with respect
% to the generator and not the origin of the domain.
x = x - mean(x);
y = y - mean(y);

% summations for CCW boundary. Direct application of Green's theorem to
% compute quntities over the polygon
xp = x( [2:end 1] );
yp = y( [2:end 1] );
a = x.*yp - xp.*y;

A = sum( a ) /2;
A=abs(A); 

end

transition.m:
function y = transition(x,spec)

arguments
    x (1,1) double {mustBeNonnegative}
    spec (1,:) char
end

if x >= 1
    y = 0;
else
    switch spec
        case 'indicator'
            y = 1;
        case 'mollifier'
            y = exp(1-1/(1-x^2));
        case 'cubic'
            y = 2*x^3 - 3*x^2 + 1;
        case 'linear'
            y = 1-x;
        case 'expReciprocal'
            y = exp(-1/(1-x)) / (exp(-1/x)+exp(-1/(1-x)));
    end
end

voronoiForwardArea.m:
function [A, verts] = voronoiForwardArea(DT,U)
arguments
    DT delaunayTriangulation
    U (:,2) double {mustBeCompatible(U,DT)}
end

N = size(U,1);
verts = cell(N,1);
A = Inf(N,1);
Ul = ([0 -1; 1 0]*U')';
Ur = ([0 1; -1 0]*U')';
Ql = voronoiProjectToBoundary(DT,Ul);
Qr = voronoiProjectToBoundary(DT,Ur);
infArea = (Ql(:,1)==Inf)|(Qr(:,1)==Inf);

X = DT.Points;
[V,C] = voronoiDiagram(DT);
al = atan2(Ql(:,2)-X(:,2), Ql(:,1)-X(:,1));
ar = atan2(Qr(:,2)-X(:,2), Qr(:,1)-X(:,1));

CH = convexHull(DT);
IN = setdiff(1:N, CH);
[~,X_bd] = freeBoundary(DT);
d = circshift(X_bd,-1,1) - X_bd;
unbd_edge_arg = atan2(d(:,2),d(:,1))-pi/2;
unbd_edge_arg = unbd_edge_arg + 2*pi*(unbd_edge_arg < -pi);

for l = 1:size(IN,2)
    i = IN(l);
    v = V(C{i},:);
    numverts = size(v,1);
    a = atan2( v(:,2)-X(i,2), v(:,1)-X(i,1) );
    [~,S] = sort([a' al(i) ar(i)]);
    S = circshift(S, 1-find(S==numverts+2,1));
    k = find(S==numverts+1,1);
    P = [Qr(i,:); v(S(2:k-1)',:); Ql(i,:)];
    verts{i} = P;
    A(i) = poly_area(P(:,1), P(:,2));
end

m = size(CH,1)-1;
for l=1:m
    i = CH(l);                      % idx of generator on convex hull
    if infArea(i) == true
        continue;
    end
    v = V(C{i},:);                  % vertices of i's voronoi cell
    numverts = size(v,1)-1;         % number of (finite) vertices of v
    a = zeros(numverts+2,1);        % initialize arrary of angles in [-pi,pi] w.r.t. generator
    a(1) = unbd_edge_arg(l);        % angle of clockwise-out unbouded edge
    a(2:end-1) = atan2( v(2:end,2)-X(i,2), v(2:end,1)-X(i,1) ); % angles to bounded vertices in counterclockwise order
    a(end) = unbd_edge_arg(l-1 + m*(l==1));      % angle of counterclockwise-out unbounded edge
    [~,S] = sort([a' al(i) ar(i)]); % append 9 and 3 o'clock angles w.r.t. U(i)'s 12 o'clock and sort
    S = circshift(S, 1-find(S==numverts+4,1));  % permute cyclically to put 3 o'clock in 1st position
    k = find(S == numverts+3, 1);   % locate sorted position of 9 o'clock
    kin = find(S==1, 1);            % -----------//------------ clockwise-out unbounded edge direction
    kout = find(S==numverts+2,1);   % -----------//------------ counterclockwise-out unbounded edge direction
    if kin < k || kout < k          % if either unbounded direction is forward-visible, continue to next iteration
        continue;
    end
    P = [Qr(i,:); v(S(2:k-1)',:); Ql(i,:)];     % else, find polygon
    verts{i} = P;
    A(i) = poly_area(P(:,1), P(:,2));
end

end

% validation
function mustBeCompatible(U,DT)
    if size(U,1) ~= size(DT.Points,1)
        eid = 'Size:notEqual';
        msg = 'Number of rows of second input must match the number of points in the triangulation.';
        throwAsCaller(MException(eid,msg));
    end
end

voronoiProjectToBoundary.m:
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Input:
%   DT  :   delaunayTriangulation object with N generators
%   U   :   Nx2 double array where each row represents the projection
%           vector for the corresponding generator. Each row is assumed to 
%           have unit norm.
% Output:
%   Q   :   Nx2 double array. Row i are the coordinates of the projection
%           of generator i along direction U(i,:) onto the boundary of the
%           Voronoi cell generated by i. 
%   r   :   Nx1 double column vector. r(i) is the distance beween generator
%           i and the projected point Q(i,:). 
%   E   :   mx3 double array where m is the number of generators in the
%           convex hull of DT. The i-th row of E represents the unbounded
%           edge e which comes in counterclockwise from infinity of the
%           Voronoi cell whose generator is the i-th element of
%           convexHull(DT). Specifically, E(i,1) and E(i,2) are the x and y
%           coordinates of the (finite) vertex of e and E(i,3) is the angle
%           in [-pi,pi] at which e radiates to infinity.
%
% NOTES:
%   - If the ray intersects the Voronoi boundary only at infinity, then
%     Q(i,:) is set to [Inf Inf] and r(i) to Inf.
%   - All computations are numerical. In particular, this may result in
%     significant error in the intersections point calculation when U(i,:) 
%     is nearly parallel to an unbounded edge of the corresponding Voronoi
%     cell.
%   - The third output E is useful primarily for plotting the Voronoi
%     diagram with its unbounded edges. The elements of E are necessary in
%     computation of Q and r so no unecessary calculation is being
%     performed is E is omitted.

function [Q,r,E] = voronoiProjectToBoundary(DT, U)

arguments
    DT delaunayTriangulation
    U (:,2) double {mustBeCompatible(U,DT)}
end

X = DT.Points;
N = size(X,1);

Q = zeros(N,2);
r = zeros(N,1);

CH = convexHull(DT);
[V,C] = voronoiDiagram(DT);

bounds = [min([V; X],[],1) max([V(2:end,:); X],[],1)];    % [xmin ymin xmax ymax] among generators and (bounded) Voronoi vertices
L = 2*(bounds(3)-bounds(1) + bounds(4)-bounds(2));      % L > distance from any generator to any finite Voronoi vertex

%% Computes the direction each unbounded Voronoi edge radiates from its bounded vertex
%  unbd_edge_arg(i) stores the direction of the Voronoi edge between the
%  i-th and (i+1)-st generators on the convex hull, i.e., CH(i) and
%  CH(i+1), as (floating point) number in [0,2pi). 

[~,X_bd] = freeBoundary(DT);
d = circshift(X_bd,-1,1) - X_bd;
unbd_edge_arg = atan2(d(:,2),d(:,1))-pi/2;
unbd_edge_arg = unbd_edge_arg + 2*pi*(unbd_edge_arg < -pi);

%% Compute intersections for interior generators

IN = setdiff(1:N, CH)';  % indices of interior generators
for l = 1:size(IN)
    i = IN(l);
    a = atan2(U(i,2),U(i,1));
    rayx = [ X(i,1) X(i,1)+L*cos(a) ];
    rayy = [ X(i,2) X(i,2)+L*sin(a) ];
    c = V(C{IN(l)},:);
    c_close = [c; c(1,:)];
    [xi,yi] = polyxpoly(rayx,rayy,c_close(:,1),c_close(:,2));
    Q(i,:) = [xi yi];
    r(i) = norm( X(i,:) - [xi yi] );
end

%% Compute intersections for boundary generators

m = size(CH,1)-1;
E = zeros(m,3);

for l = 1:m
    i = CH(l);
    c = V(C{i},:);  
    a = atan2(U(i,2),U(i,1));
    a1 = unbd_edge_arg(l);
    a2 = atan2(c(2,2)-X(i,2), c(2,1)-X(i,1));
    a3 = atan2(c(end,2)-X(i,2), c(end,1)-X(i,1));
    a4 = unbd_edge_arg(1+mod(l-2,m));
    [~,S] = sort([a,a1,a2,a3,a4]);
    S = circshift(S, 1-find(S==1));
    switch S(2)
        case 2  % intersect Voronoi boundary at infinity
            xi = Inf; yi = Inf;
        case 3  % intersect unbounded edge counterclockwise incoming from infinity
            p = c(2,:);
%             t = ( U(i,1)*(p(2)-X(i,2)) - U(i,2)*(p(1)-X(i,1)) );
%             t = t/(U(i,2)*cos(a1) - U(i,1)*sin(a1));
            d = p-X(i,:);
            b = atan2(d(2),d(1));
            h = atan2(U(i,2),U(i,1));
            t = -norm(d)*sin(h-b)*csc(h-a1);
            xi = p(1) + t*cos(a1);
            yi = p(2) + t*sin(a1);
        case 4  % intersect bounded edge
            rayx = [ X(i,1) X(i,1)+L*cos(a) ];
            rayy = [ X(i,2) X(i,2)+L*sin(a) ];
            [xi,yi] = polyxpoly(rayx,rayy,c(2:end,1),c(2:end,2));
        case 5  % intersect unbounded edge counterclockwise outgoing to infinity
            p = c(end,:);
%             t = ( U(i,1)*(p(2)-X(i,2)) - U(i,2)*(p(1)-X(i,1)) );
%             t = t/(U(i,2)*cos(a4) - U(i,1)*sin(a4));
            d = p-X(i,:);
            b = atan2(d(2),d(1));
            h = atan2(U(i,2),U(i,1));
            t = -norm(d)*sin(h-b)*csc(h-a4);
            xi = p(1) + t*cos(a4);
            yi = p(2) + t*sin(a4);
   end
    Q(i,:) = [xi yi];
    r(i) = norm( Q(i,:) - X(i,:) );
    E(l,:) = [ c(2,:) a1 ];
end

end

% validation
function mustBeCompatible(U,DT)
    if size(U,1) ~= size(DT.Points,1)
        eid = 'Size:notEqual';
        msg = 'Number of rows of second input must match the number of points in the triangulation.';
        throwAsCaller(MException(eid,msg));
    end
end
